<?php session_start();require_once "db.php";if(!isset($_SESSION["uid"])){header("Location: login.php");exit;}$s=$conn->prepare("SELECT o.*,m.name item FROM orders o JOIN menu_items m ON o.item_id=m.id WHERE o.user_id=? ORDER BY o.created_at DESC");$s->bind_param("i",$_SESSION["uid"]);$s->execute();$rows=$s->get_result();?>
<!doctype html><html><head><title>Orders</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="container"><h2>Welcome <?=htmlspecialchars($_SESSION["uname"])?></h2><a href="index.php">Restaurants</a> · <a href="logout.php">Logout</a><h3>My Orders</h3><table><tr><th>Item</th><th>Qty</th><th>Total</th><th>Status</th><th>Address</th></tr><?php while($o=$rows->fetch_assoc()): ?><tr><td><?=htmlspecialchars($o["item"])?></td><td><?=$o["quantity"]?></td><td>₹<?=number_format($o["total"],2)?></td><td><?=htmlspecialchars($o["status"])?></td><td><?=htmlspecialchars($o["address"])?></td></tr><?php endwhile;?></table></main></body></html>